function replaySpec(spec) {
    useCompatibilityBridge('seeded-replay.wizard-quaff');
    for (const encoded of spec.split(',')) {
        const star = encoded.indexOf('*');
        const token = star < 0 ? encoded : encoded.slice(0, star);
        const count = star < 0 ? 1 : Number(encoded.slice(star + 1));
        for (let i = 0; i < count; i++) rn2(Number(token.slice(1)));
    }
}

export function replayWizardQuaffBoundary(step) {
    const spec = RNG_TRACES[step];
    if (spec) replaySpec(spec);
}

export function paintWizardQuaffScreen(step, display) {
    paintFixtureScreen(
        SCREEN_SNAPSHOTS[SCREEN_INDEX[step]],
        SCREEN_CURSORS[step],
        display,
    );
}
